+func TestExitCodeOfAWrappedKogenError(t *testing.T) {
+	parallel(t)
+	kogen := sys.Fail("shape", "refused", "detail", 4)
+	wrapped := fmt.Errorf("outer: %w", fmt.Errorf("middle: %w", kogen))
+	shpEq(t, "exit of a wrapped Kogen error", ExitCode(wrapped), 4)
+}
+
+func TestExitCodeOfAWrappedInterruption(t *testing.T) {
+	parallel(t)
+	for signal, want := range map[string]int{"SIGINT": 130, "SIGTERM": 143, "SIGHUP": 129} {
+		wrapped := fmt.Errorf("outer: %w", fmt.Errorf("middle: %w", &sys.Interrupted{Signal: signal}))
+		shpEq(t, "exit of a wrapped interruption by "+signal, ExitCode(wrapped), want)
+	}
+}
+
+func TestExitCodeOfAnUnrelatedWrappedError(t *testing.T) {
+	parallel(t)
+	wrapped := fmt.Errorf("outer: %w", fmt.Errorf("middle: %w", os.ErrNotExist))
+	shpEq(t, "exit of an unrelated wrapped error", ExitCode(wrapped), 70)
+}

